create table if not exists public.game_sessions (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id) on delete cascade,status text not null default 'ACTIVE' check(status in('ACTIVE','PAUSED','ENDED')),turn_count integer not null default 0 check(turn_count>=0),started_at timestamptz not null default now(),last_active_at timestamptz not null default now());
create index if not exists game_sessions_campaign_idx on public.game_sessions(campaign_id,last_active_at desc);
create table if not exists public.game_turns (id bigserial primary key,session_id uuid not null references public.game_sessions(id) on delete cascade,campaign_id uuid not null references public.campaigns(id) on delete cascade,turn_no integer not null,speaker text not null check(speaker in('PLAYER','GM','SYSTEM')),content text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(session_id,turn_no,speaker));
create index if not exists game_turns_session_idx on public.game_turns(session_id,turn_no);
alter table public.game_sessions enable row level security; alter table public.game_sessions force row level security;
alter table public.game_turns enable row level security; alter table public.game_turns force row level security;
create policy sessions_owner on public.game_sessions for all to authenticated using(exists(select 1 from public.campaigns c where c.id=campaign_id and c.owner_id=(select auth.uid()))) with check(exists(select 1 from public.campaigns c where c.id=campaign_id and c.owner_id=(select auth.uid())));
create policy turns_owner on public.game_turns for select to authenticated using(exists(select 1 from public.campaigns c where c.id=campaign_id and c.owner_id=(select auth.uid())));
